// Validate this is a merged Renovate PR
const input = $input.first().json;
const body = input.body || input;

// Must be a closed + merged pull request
if (body.action !== 'closed' || !body.pull_request?.merged) {
  return [];
}

const pr = body.pull_request;

// Must be merged into main
if (pr.base.ref !== 'main') {
  return [];
}

const branch = pr.head.ref;

// Must be from Renovate (branch pattern or 'dependencies' label)
const isRenovate =
  branch.startsWith('renovate/') ||
  branch.startsWith('renovate-') ||
  pr.labels?.some(l => l.name === 'dependencies');

if (!isRenovate) {
  throw new Error('Not a Renovate PR (branch: ' + branch + ') — execution cancelled');
}

return [{
  json: {
    prNumber: pr.number,
    prTitle: pr.title,
    branch,
    repoFullName: body.repository.full_name,
  }
}];

// Extract unique helmfile directories from changed files and build deploy command
const files = $input.all();
const prInfo = $('Validate Renovate PR').first().json;

// Match files under kubernetes/apps/<name>/ or kubernetes/infra/<name>/
const deployDirs = new Set();
const pattern = /^kubernetes\/(apps|infra)\/([^/]+)\//;

for (const item of files) {
  const match = item.json.filename.match(pattern);
  if (match) {
    deployDirs.add(`kubernetes/${match[1]}/${match[2]}`);
  }
}

if (deployDirs.size === 0) {
  return [];
}

const dirs = Array.from(deployDirs);
const REPO_PATH = '/home/k/projects/homelab';

const deploySteps = dirs.map(dir => [
  `echo ">>> Deploying ${dir}..."`,
  `cd "${REPO_PATH}/${dir}"`,
  `helmfile apply`,
  // Restart deployments in the release namespace to handle stale mounts/pods
  `NS=$(grep 'namespace:' helmfile.yaml | head -1 | awk '{print $2}')`,
  `kubectl rollout restart deployment -n "$NS" 2>/dev/null || true`,
].join(' && ')).join(' && ');

const script = `set -euo pipefail
cd "${REPO_PATH}"

# Save current branch
PREV_BRANCH=$(git rev-parse --abbrev-ref HEAD)
STASH_BEFORE=$(git stash list | wc -l)

# Cleanup: always restore branch and stash on exit
cleanup() {
  cd "${REPO_PATH}"
  git checkout "$PREV_BRANCH" 2>/dev/null || true
  STASH_AFTER=$(git stash list | wc -l)
  if [ "$STASH_AFTER" -gt "$STASH_BEFORE" ]; then
    git stash pop 2>/dev/null || true
  fi
}
trap cleanup EXIT

# Stash local changes and switch to main
git stash --include-untracked 2>/dev/null || true
git checkout main
git fetch origin main
git merge --ff-only origin/main

# Load environment and deploy
source .envrc
${deploySteps}`;

return [{
  json: {
    command: script,
    apps: dirs,
    appCount: dirs.length,
    prTitle: prInfo.prTitle,
    prNumber: prInfo.prNumber,
  }
}];
